 'If Email verification is on, Customers must verify their Email with an verification code to complete the signup process.' => 'ইমেল যাচাইকরণ চালু থাকলে, সাইন আপ প্রক্রিয়াটি সম্পূর্ণ করতে গ্রাহকদের অবশ্যই একটি যাচাইকরণ কোড দিয়ে তাদের ইমেল যাচাই করতে হবে।',
 'If Phone Number verification is on, Customers must verify their Phone Number with an OTP to complete the signup process.' => 'যদি ফোন নম্বর যাচাইকরণ চালু থাকে, তাহলে সাইন আপ প্রক্রিয়াটি সম্পূর্ণ করতে গ্রাহকদের অবশ্যই একটি OTP দিয়ে তাদের ফোন নম্বর যাচাই করতে হবে।',
 'If SMTP configuration is disabled or incorrect, the system will not be able to send any email notifications.' => 'SMTP কনফিগারেশন অক্ষম বা ভুল হলে, সিস্টেম কোনো ইমেল বিজ্ঞপ্তি পাঠাতে সক্ষম হবে না।',
 'If disabled Subscription, All subscriber moved to commission and providers have to give a certain percentage of commission to admin for every booking request' => 'সাবস্ক্রিপশন অক্ষম করা হলে, সমস্ত গ্রাহক কমিশনে চলে যাবে এবং প্রদানকারীদের প্রতিটি বুকিং অনুরোধের জন্য প্রশাসককে একটি নির্দিষ্ট শতাংশ কমিশন দিতে হবে',
 'If disabled customers and provider will not receive notifications on their devices' => 'যদি অক্ষম গ্রাহক এবং প্রদানকারী তাদের ডিভাইসে বিজ্ঞপ্তি পাবেন না',
 'If disabled customers can not pay through this payment methods' => 'যদি অক্ষম গ্রাহকরা এই পেমেন্ট পদ্ধতির মাধ্যমে অর্থ প্রদান করতে না পারেন',
 'If enable this, newly uploaded/created files and data will store to 3rd party storage.' => 'এটি সক্ষম হলে, নতুন আপলোড/তৈরি করা ফাইল এবং ডেটা তৃতীয় পক্ষের স্টোরেজে সংরক্ষণ করা হবে।',
 'If enable this, newly uploaded/created files and data will store to local storage.' => 'এটি সক্ষম হলে, নতুন আপলোড করা/তৈরি করা ফাইল এবং ডেটা স্থানীয় স্টোরেজে সংরক্ষণ করা হবে।',
 'If enabled System will store all files and images to 3rd party storage' => 'সক্ষম হলে সিস্টেম সমস্ত ফাইল এবং ছবি তৃতীয় পক্ষের স্টোরেজে সংরক্ষণ করবে',
 'If enabled System will store all files and images to local storage' => 'সক্ষম হলে সিস্টেম স্থানীয় স্টোরেজে সমস্ত ফাইল এবং ছবি সংরক্ষণ করবে',
 'If enabled customers can only pay through this payment methods' => 'সক্ষম হলে গ্রাহকরা শুধুমাত্র এই অর্থপ্রদান পদ্ধতির মাধ্যমে অর্থ প্রদান করতে পারেন',
 'If enabled, Serviceman can cancel a booking request after it has been place' => 'যদি সক্ষম করা হয়, সার্ভিসম্যান একটি বুকিং অনুরোধটি স্থাপন করার পরে বাতিল করতে পারে৷',
 'If enabled, Serviceman can edit a booking request after it has been place' => 'যদি সক্ষম করা হয়, সার্ভিসম্যান একটি বুকিং অনুরোধটি স্থাপন করার পরে সম্পাদনা করতে পারে৷',
 'If enabled, provider can delete account' => 'সক্ষম হলে, প্রদানকারী অ্যাকাউন্ট মুছে ফেলতে পারে',
 'If enabled, providers can cancel a booking even after it has been placed.' => 'যদি সক্ষম করা হয়, প্রদানকারীরা একটি বুকিং রাখার পরেও এটি বাতিল করতে পারে৷',
 'If enabled, providers can do self-registration from the admin landing page, provider panel & app, and customer website & app.' => 'সক্ষম হলে, প্রদানকারীরা অ্যাডমিন ল্যান্ডিং পৃষ্ঠা, প্রদানকারী প্যানেল এবং অ্যাপ এবং গ্রাহক ওয়েবসাইট এবং অ্যাপ থেকে স্ব-নিবন্ধন করতে পারে।',
 'If enabled, providers can edit a booking request after it has been placed' => 'সক্ষম হলে, প্রদানকারীরা একটি বুকিং অনুরোধটি স্থাপন করার পরে সম্পাদনা করতে পারে৷',
 'If enabled, providers can review reply' => 'সক্ষম হলে, প্রদানকারীরা উত্তর পর্যালোচনা করতে পারে',
 'If enabled, the provider will be automatically suspended by the system when their ‘Cash in Hand’ limit is exceeded.' => 'যদি সক্ষম করা থাকে, প্রদানকারীকে স্বয়ংক্রিয়ভাবে সিস্টেম দ্বারা স্থগিত করা হবে যখন তাদের \'ক্যাশ ইন হ্যান্ড\' সীমা অতিক্রম করবে।',
 'If no access is selected, employees with this role can only view the section for which permissions are granted; they cannot perform any actions.' => 'যদি কোনও অ্যাক্সেস নির্বাচন না করা হয়, এই ভূমিকার কর্মচারীরা শুধুমাত্র সেই বিভাগটি দেখতে পারে যার জন্য অনুমতি দেওয়া হয়েছে; তারা কোনো কাজ করতে পারে না।',
 'If the maximum limit is exceeded, the provider will be suspended and will not receive any service requests.' => 'সর্বোচ্চ সীমা অতিক্রম করলে, প্রদানকারীকে স্থগিত করা হবে এবং কোনো পরিষেবার অনুরোধ পাবেন না।',
 'If the required permissions are not in place, you’ll need to manually configure the cron job by adding the following command to your server’s crontab' => 'যদি প্রয়োজনীয় অনুমতিগুলি না থাকে, তাহলে আপনাকে আপনার সার্ভারের ক্রনট্যাবে নিম্নলিখিত কমান্ডটি যোগ করে ক্রোন কাজটি ম্যানুয়ালি কনফিগার করতে হবে',
 'If there is any update available in the admin panel and the previous app will not work with it.' => 'অ্যাডমিন প্যানেলে কোনো আপডেট পাওয়া গেলে এবং আগের অ্যাপটি এটি দিয়ে কাজ করবে না।',
 'If this feature is active customers get the otp through firebase.' => 'এই বৈশিষ্ট্যটি সক্রিয় থাকলে গ্রাহকরা ফায়ারবেসের মাধ্যমে ওটিপি পান।',
 'If want to Update it for all upcoming bookings' => 'সব আসন্ন বুকিং জন্য এটি আপডেট করতে চান',
 'If you activate reCAPTCHA, please ensure that reCAPTCHA v3 is properly set up beforehand.' => 'আপনি reCAPTCHA সক্রিয় করলে, অনুগ্রহ করে নিশ্চিত করুন যে reCAPTCHA v3 আগে থেকেই সঠিকভাবে সেট-আপ করা আছে।',
 'If you approve it, it will remain expired.' => 'আপনি যদি এটি অনুমোদন করেন তবে এটি মেয়াদোত্তীর্ণ থাকবে।',
 'If you are using a different path, find your mysqldump by running the command "which mysqldump" or "locate mysqldump" in your terminal, or ask your server provider.' => 'আপনি যদি একটি ভিন্ন পথ ব্যবহার করেন, তাহলে আপনার টার্মিনালে "which mysqldump" বা "locate mysqldump" কমান্ডটি চালিয়ে আপনার mysqldump খুঁজুন বা আপনার সার্ভার প্রদানকারীকে জিজ্ঞাসা করুন।',
 'If you cancel the subscription, after :countDays days the Provider will no longer be able to run the business before subscribe a new plan' => 'আপনি সাবস্ক্রিপশন বাতিল করলে, :countDays দিন পরে প্রোভাইডার নতুন প্ল্যান সাবস্ক্রাইব করার আগে আর ব্যবসা চালাতে পারবে না',
 'If you close now, the progress made so far will be saved.' => 'আপনি যদি এখন বন্ধ করেন, এখন পর্যন্ত করা অগ্রগতি সংরক্ষণ করা হবে।',
 'If you close the tab, the progress made will be saved but remaining content will not be translated.' => 'আপনি যদি ট্যাবটি বন্ধ করেন তবে অগ্রগতি সংরক্ষণ করা হবে কিন্তু অবশিষ্ট সামগ্রী অনুবাদ করা হবে না।',
 'If you do not have any project yet, create one with the website name.' => 'আপনার যদি এখনও কোনো প্রজেক্ট না থাকে, তাহলে ওয়েবসাইট নাম দিয়ে একটি তৈরি করুন।',
 'If you do not need a force update, just insert zero (0) here and ignore it.' => 'আপনার যদি ফোর্স আপডেটের প্রয়োজন না হয় তবে এখানে শূন্য (0) ঢোকান এবং এটি উপেক্ষা করুন।',
 'If you don’t have any project before. Create one with the website name' => 'যদি আপনার আগে কোন প্রজেক্ট না থাকে। ওয়েবসাইটের নাম দিয়ে একটি তৈরি করুন',
 'If you have not created any project for your application yet, please create one first.' => 'আপনি যদি এখনও আপনার অ্যাপ্লিকেশনের জন্য কোনো প্রকল্প তৈরি না করে থাকেন, অনুগ্রহ করে প্রথমে একটি তৈরি করুন।',
 'If you have questions or need assistance, contact our support team.' => 'আপনার যদি প্রশ্ন থাকে বা সহায়তার প্রয়োজন হয়, আমাদের সহায়তা দলের সাথে যোগাযোগ করুন।',
 'If you need assistance, contact our support team.' => 'আপনার যদি সহায়তার প্রয়োজন হয়, আমাদের সহায়তা দলের সাথে যোগাযোগ করুন।',
 'If you select repeat booking, the customer can place the same service booking for multiple dates under one booking' => 'আপনি যদি পুনরাবৃত্ত বুকিং নির্বাচন করেন, তাহলে গ্রাহক একটি বুকিংয়ের অধীনে একাধিক তারিখের জন্য একই পরিষেবা বুকিং রাখতে পারেন',
 'If you switch this newly uploaded created files & data will store to 3rd party storage' => 'আপনি যদি এই নতুন আপলোড করা ফাইলগুলি স্যুইচ করেন এবং ডেটা তৃতীয় পক্ষের স্টোরেজে জমা হবে৷',
 'If you switch this newly uploaded created files & data will store to local storage' => 'আপনি যদি এই নতুন আপলোড করা ফাইলগুলি স্যুইচ করেন এবং ডেটা স্থানীয় স্টোরেজে জমা হবে৷',
 'If you turn of the availability status, this page will not show in the customer app and website' => 'আপনি প্রাপ্যতার স্থিতি চালু করলে, এই পৃষ্ঠাটি গ্রাহক অ্যাপ এবং ওয়েবসাইটে দেখাবে না',
 'If you turn off customer can`t pay through this payment gateway.' => 'আপনি বন্ধ করে দিলে গ্রাহক এই পেমেন্ট গেটওয়ের মাধ্যমে পেমেন্ট করতে পারবেন না।',
 'If you turn off customer can`t pay through this payment geteway.' => 'আপনি বন্ধ করে দিলে গ্রাহক এই পেমেন্ট গেটওয়ের মাধ্যমে পেমেন্ট করতে পারবেন না।',
 'If you turn on The Status, this payment will show in dropdown list when withdraw request sent to admin.' => 'আপনি স্ট্যাটাস চালু করলে, প্রশাসকের কাছে প্রত্যাহারের অনুরোধ পাঠানো হলে এই অর্থপ্রদান ড্রপডাউন তালিকায় দেখা যাবে।',
 'If you turn on the switch, this feature will be active and customers can make scheduled orders after the restriction time ends.' => 'আপনি যদি সুইচটি চালু করেন, এই বৈশিষ্ট্যটি সক্রিয় হবে এবং গ্রাহকরা সীমাবদ্ধতার সময় শেষ হওয়ার পরে নির্ধারিত অর্ডার করতে পারবেন।',
 'If you want to use third-party storage, set up the connection with :third_party_storage_link.' => 'আপনি যদি তৃতীয় পক্ষের স্টোরেজ ব্যবহার করতে চান, :third পার্টি স্টোরেজ লিঙ্কের সাথে সংযোগ সেট আপ করুন।',
 'If you want, you can activate all 3 options based on your business need.' => 'আপনি যদি চান, আপনি আপনার ব্যবসার প্রয়োজনের উপর ভিত্তি করে সমস্ত 3টি বিকল্প সক্রিয় করতে পারেন।',
 'If your servers DUMP BINARY PATH does not match the following input field path, you must update it.' => 'যদি আপনার সার্ভারগুলি ডাম্প বাইনারি PATH নিম্নলিখিত ইনপুট ক্ষেত্রের পথের সাথে মেলে না, তাহলে আপনাকে অবশ্যই এটি আপডেট করতে হবে৷',
 'Ignore' => 'উপেক্ষা করুন',
 'Ignore/Reject' => 'উপেক্ষা/প্রত্যাখ্যান করুন',
