 'In the left-hand menu, click on the' => 'বামদিকের মেনুতে, ক্লিক করুন',
 'In this package you received' => 'এই প্যাকেজ আপনি পেয়েছেন',
 'In this page you can add, edit and status On/Off your business related pages.' => 'এই পৃষ্ঠায় আপনি আপনার ব্যবসা সম্পর্কিত পৃষ্ঠাগুলি যোগ করতে, সম্পাদনা করতে এবং স্থিতি চালু/বন্ধ করতে পারেন।',
 'In this section, you can add offline payment methods to make them available as offline payment options for the customers' => 'এই বিভাগে, আপনি অফলাইন অর্থপ্রদানের পদ্ধতিগুলিকে গ্রাহকদের জন্য অফলাইন অর্থপ্রদানের বিকল্প হিসাবে উপলব্ধ করতে যোগ করতে পারেন৷',
 'In this settings admin can set the rules for the customers for earning and use the loyalty points.' => 'এই সেটিংসে অ্যাডমিন গ্রাহকদের জন্য আয়ের নিয়ম সেট করতে পারেন এবং লয়্যালটি পয়েন্ট ব্যবহার করতে পারেন।',
