 'Insert the wrong PHP file path - Copy the correct path and input it in the PHP file path Section' => 'ভুল পিএইচপি ফাইল পাথ সন্নিবেশ করুন - সঠিক পথটি অনুলিপি করুন এবং এটি পিএইচপি ফাইল পাথ বিভাগে ইনপুট করুন',
