 'Once you turn off the Category Status, the Provider can’t subscribe to the services of that category and the Customer can’t find the category & its service when they want to book' => 'একবার আপনি ক্যাটাগরি স্ট্যাটাস বন্ধ করে দিলে, প্রোভাইডার সেই ক্যাটাগরির পরিষেবাগুলিতে সাবস্ক্রাইব করতে পারবেন না এবং গ্রাহক যখন বুক করতে চান তখন ক্যাটাগরি এবং তার পরিষেবা খুঁজে পাবেন না',
 'Once you turn off the Zone Status it will impact the category, services, and location finding for customers' => 'একবার আপনি জোন স্ট্যাটাস বন্ধ করলে এটি গ্রাহকদের জন্য বিভাগ, পরিষেবা এবং অবস্থান অনুসন্ধানকে প্রভাবিত করবে',
 'Once you turn off the page status, it will be hidden from users.' => 'একবার আপনি পৃষ্ঠার স্থিতি বন্ধ করে দিলে, এটি ব্যবহারকারীদের কাছ থেকে লুকানো হবে।',
 'Once you turn on the Category Status, the user can find the Category and its service for selection' => 'একবার আপনি বিভাগ স্থিতি চালু করলে, ব্যবহারকারী নির্বাচনের জন্য বিভাগ এবং এর পরিষেবা খুঁজে পেতে পারেন',
 'Once you turn on the Zone Status, the user can find the category, services, and location in that zone' => 'একবার আপনি জোন স্ট্যাটাস চালু করলে, ব্যবহারকারী সেই জোনে বিভাগ, পরিষেবা এবং অবস্থান খুঁজে পেতে পারেন',
