 'Please contact our support team to learn more about the reason for this suspension and the steps to reinstate your account.' => 'এই সাসপেনশনের কারণ এবং আপনার অ্যাকাউন্ট পুনঃস্থাপনের পদক্ষেপগুলি সম্পর্কে আরও জানতে অনুগ্রহ করে আমাদের সহায়তা দলের সাথে যোগাযোগ করুন৷',
