 'The Access Key ID is a publicly accessible identifier used to authenticate requests to S3.' => 'অ্যাক্সেস কী আইডি হল একটি সর্বজনীনভাবে অ্যাক্সেসযোগ্য শনাক্তকারী যা S3-তে অনুরোধগুলি প্রমাণীকরণ করতে ব্যবহৃত হয়।',
 'The Admin Notification Setup for booking allows the administrator to configure how system notifications are sent and managed. Admin notifications can be delivered either manually or through Firebase, depending on the selected configuration' => 'বুকিংয়ের জন্য অ্যাডমিন নোটিফিকেশন সেটআপ অ্যাডমিনিস্ট্রেটরকে কীভাবে সিস্টেম বিজ্ঞপ্তি পাঠানো এবং পরিচালনা করা হয় তা কনফিগার করতে দেয়। নির্বাচিত কনফিগারেশনের উপর নির্ভর করে প্রশাসক বিজ্ঞপ্তিগুলি ম্যানুয়ালি বা Firebase এর মাধ্যমে বিতরণ করা যেতে পারে',
 'The Business name often serves as the primary identifier for your business as a legal entity.' => 'ব্যবসার নাম প্রায়ই একটি আইনি সত্তা হিসাবে আপনার ব্যবসার প্রাথমিক শনাক্তকারী হিসাবে কাজ করে।',
 'The Country Name field, when setting up a business is essential for a multitude of reasons, spanning legal, operational, financial, and marketing aspects.' => 'কান্ট্রি নেম ফিল্ড, যখন একটি ব্যবসা সেট আপ করার জন্য আইনী, কর্মক্ষম, আর্থিক এবং বিপণন দিকগুলি বিস্তৃত বহুবিধ কারণে অপরিহার্য।',
 'The Cron Job PHP configuration error occurs when' => 'ক্রন জব পিএইচপি কনফিগারেশন ত্রুটি ঘটে যখন',
 'The Customer will come to the your Location to receive the service' => 'গ্রাহক পরিষেবাটি পেতে আপনার অবস্থানে আসবেন',
