 'The Service Location will be available after this booking accepts or assign to a provider' => 'এই বুকিং গ্রহণ বা প্রদানকারীকে বরাদ্দ করার পরে পরিষেবার অবস্থান উপলব্ধ হবে৷',
 'The Service Location will be available after this booking assign to a provider' => 'পরিষেবার অবস্থান এই বুকিং প্রদানকারীকে প্রদান করার পরে উপলব্ধ হবে৷',
