 'The customer who used referral code will get discount when a place their first order.' => 'যে গ্রাহক রেফারেল কোড ব্যবহার করেছেন তারা তাদের প্রথম অর্ডার দিলেই ছাড় পাবেন।',
 'The discount amount value must be gather than 0' => 'ছাড়ের পরিমাণের মান অবশ্যই 0 এর থেকে সংগ্রহ করতে হবে',
 'The discount percent value must be gather than 0' => 'ডিসকাউন্ট শতাংশ মান 0 থেকে সংগ্রহ করা আবশ্যক',
 'The execution time of a cron job is defined by the schedule when the job will be done.' => 'একটি ক্রন কাজের সম্পাদনের সময় সময়সূচী দ্বারা সংজ্ঞায়িত করা হয় কখন কাজটি করা হবে।',
 'The fav icon helps users quickly identify the site among multiple open tabs.' => 'fav আইকন ব্যবহারকারীদের একাধিক খোলা ট্যাবের মধ্যে দ্রুত সাইট শনাক্ত করতে সাহায্য করে।',
 'The minimum number of points a customer must have before converting them into wallet money.' => 'ওয়ালেট মানিতে রূপান্তর করার আগে একজন গ্রাহকের ন্যূনতম সংখ্যক পয়েন্ট থাকতে হবে।',
 'The name of the s3 bucket where your files will be stored.' => 's3 বাকেটের নাম যেখানে আপনার ফাইল সংরক্ষণ করা হবে।',
 'The option you select customer will have the option to login customer app and websites' => 'আপনি যে বিকল্পটি গ্রাহক নির্বাচন করবেন তাতে গ্রাহক অ্যাপ এবং ওয়েবসাইট লগইন করার বিকল্প থাকবে',
 'The option you select customer will have the to option to login' => 'আপনি গ্রাহক যে বিকল্পটি নির্বাচন করবেন তাতে লগইন করার বিকল্প থাকবে',
 'The option you select customers will be able to log in to both the app and website based on the option you select.' => 'আপনি যে বিকল্পটি নির্বাচন করবেন গ্রাহকরা আপনার নির্বাচন করা বিকল্পের উপর ভিত্তি করে অ্যাপ এবং ওয়েবসাইট উভয়টিতে লগ ইন করতে সক্ষম হবেন।',
 'The option you select from below will need to verify by customer from customer app/website' => 'আপনি নীচের থেকে যে বিকল্পটি নির্বাচন করেছেন তা গ্রাহক অ্যাপ/ওয়েবসাইট থেকে গ্রাহক দ্বারা যাচাই করতে হবে',
 'The private key paired with your access key for secure authentication.' => 'নিরাপদ প্রমাণীকরণের জন্য ব্যক্তিগত কী আপনার অ্যাক্সেস কী-এর সাথে যুক্ত।',
 'The profile image is required' => 'প্রোফাইল ইমেজ প্রয়োজন',
 'The remaining content will not be translated.' => 'অবশিষ্ট বিষয়বস্তু অনুবাদ করা হবে না.',
 'The remaining count updates automatically as you use services. And an option to change, renew, or change the subscription plan' => 'আপনি পরিষেবাগুলি ব্যবহার করার সাথে সাথে অবশিষ্ট গণনা স্বয়ংক্রিয়ভাবে আপডেট হয়। এবং সদস্যতা পরিকল্পনা পরিবর্তন, পুনর্নবীকরণ বা পরিবর্তন করার একটি বিকল্প',
 'The service availability option has been turned off. You will not receive any new booking requests until you turn on the service availability option' => 'পরিষেবা উপলব্ধতা বিকল্পটি বন্ধ করা হয়েছে। আপনি পরিষেবা উপলব্ধতা বিকল্প চালু না করা পর্যন্ত আপনি কোন নতুন বুকিং অনুরোধ পাবেন না',
 'The service availability option has been turned off. You will not receive any new customized requests until you turn on the service availability option' => 'পরিষেবা উপলব্ধতা বিকল্পটি বন্ধ করা হয়েছে। আপনি পরিষেবা উপলব্ধতা বিকল্প চালু না করা পর্যন্ত আপনি কোনো নতুন কাস্টমাইজড অনুরোধ পাবেন না',
 'The title of a Cron Job refers to the command that will be automatically executed at specific time intervals or dates when scheduled.' => 'একটি ক্রোন কাজের শিরোনাম নির্দেশ করে যেটি নির্দিষ্ট সময়ের ব্যবধানে বা নির্ধারিত তারিখে স্বয়ংক্রিয়ভাবে কার্যকর হবে।',
 'The uploaded file must be an image.' => 'আপলোড করা ফাইলটি অবশ্যই একটি ছবি হতে হবে।',
 'Your account username' => 'আপনার অ্যাকাউন্টের ব্যবহারকারীর নাম',
 'The video attachment is required' => 'ভিডিও সংযুক্তি প্রয়োজন',
