 'This social media link has already been added. Please choose a different platform or update the existing one' => 'এই সামাজিক মিডিয়া লিঙ্ক ইতিমধ্যে যোগ করা হয়েছে. অনুগ্রহ করে একটি ভিন্ন প্ল্যাটফর্ম চয়ন করুন বা বিদ্যমান একটি আপডেট করুন৷',
 'This view is from the user app.' => 'এই ভিউ ইউজার অ্যাপ থেকে নেওয়া হয়েছে।',
