 'To enable Email verification, please set up the Email configuration and turn on the status first.' => 'ইমেল যাচাইকরণ সক্ষম করতে, অনুগ্রহ করে ইমেল কনফিগারেশন সেট আপ করুন এবং প্রথমে স্থিতিটি চালু করুন৷',
 'To enable Phone verification, please set up the SMS configuration and turn on the status first.' => 'ফোন যাচাইকরণ সক্ষম করতে, অনুগ্রহ করে এসএমএস কনফিগারেশন সেট আপ করুন এবং প্রথমে স্থিতিটি চালু করুন৷',
 'To enable map-based features such as location selection, serviceman tracking, and distance calculation, you must provide valid Google Map API keys.' => 'অবস্থান নির্বাচন, সার্ভিসম্যান ট্র্যাকিং এবং দূরত্ব গণনার মতো মানচিত্র-ভিত্তিক বৈশিষ্ট্যগুলি সক্ষম করতে, আপনাকে অবশ্যই বৈধ Google Map API কীগুলি সরবরাহ করতে হবে৷',
 'To enable the Apple ID Login option, please set up the Apple ID configuration first.' => 'অ্যাপল আইডি লগইন বিকল্পটি সক্ষম করতে, অনুগ্রহ করে প্রথমে অ্যাপল আইডি কনফিগারেশন সেট আপ করুন।',
 'To enable the Apple login system, please set up the Apple configuration first.' => 'Apple লগইন সিস্টেম সক্ষম করতে, অনুগ্রহ করে প্রথমে Apple কনফিগারেশন সেট আপ করুন৷',
 'To enable the Facebook Login option, please set up the Facebook configuration first.' => 'Facebook লগইন বিকল্পটি সক্ষম করতে, অনুগ্রহ করে প্রথমে Facebook কনফিগারেশন সেট আপ করুন৷',
 'To enable the OTP system, please set up the Google configuration first.' => 'OTP সিস্টেম সক্ষম করতে, অনুগ্রহ করে প্রথমে Google কনফিগারেশন সেট আপ করুন৷',
 'To enable the OTP system, please set up the SMS configuration first.' => 'OTP সিস্টেম সক্রিয় করতে, অনুগ্রহ করে প্রথমে এসএমএস কনফিগারেশন সেট আপ করুন।',
 'To enable the social media login system, please set up the social media configuration first.' => 'সোশ্যাল মিডিয়া লগইন সিস্টেম সক্রিয় করতে, অনুগ্রহ করে প্রথমে সোশ্যাল মিডিয়া কনফিগারেশন সেট আপ করুন৷',
 'To enable this feature must be activated' => 'এই বৈশিষ্ট্য সক্রিয় করতে হবে',
