 'To get site key and secret keyGo to the Credentials page' => 'সাইট কী এবং গোপন কী পেতে শংসাপত্র পৃষ্ঠায় যান৷',
 'To make these payment options available, you must enable the Digital payment option from the :business_information_link page.' => 'এই অর্থপ্রদানের বিকল্পগুলি উপলব্ধ করতে, আপনাকে অবশ্যই :business তথ্য লিঙ্ক পৃষ্ঠা থেকে ডিজিটাল অর্থপ্রদান বিকল্পটি সক্ষম করতে হবে।',
