 'You can also allow automatic account creation using guest information to convert guests into registered users.' => 'অতিথিদের নিবন্ধিত ব্যবহারকারীদের মধ্যে রূপান্তর করতে আপনি অতিথি তথ্য ব্যবহার করে স্বয়ংক্রিয় অ্যাকাউন্ট তৈরির অনুমতি দিতে পারেন।',
 'You can also mark a method as default, update its information, or remove it if necessary.' => 'আপনি একটি পদ্ধতিকে ডিফল্ট হিসাবে চিহ্নিত করতে পারেন, এর তথ্য আপডেট করতে পারেন, বা প্রয়োজনে এটি সরাতে পারেন।',
 'You can create an ad on behalf of a provider.' => 'আপনি একটি প্রদানকারীর পক্ষে একটি বিজ্ঞাপন তৈরি করতে পারেন৷',
 'You can force the customer from here by providing the minimum version for force update.' => 'ফোর্স আপডেটের জন্য ন্যূনতম সংস্করণ প্রদান করে আপনি এখান থেকে গ্রাহককে বাধ্য করতে পারেন।',
 'You can force the user from here by providing the minimum version for force update.' => 'ফোর্স আপডেটের জন্য ন্যূনতম সংস্করণ প্রদান করে আপনি এখান থেকে ব্যবহারকারীকে বাধ্য করতে পারেন।',
 'You can get the PHP file path from your server. Here is an example of Apache Server -' => 'আপনি আপনার সার্ভার থেকে PHP ফাইল পাথ পেতে পারেন। এখানে Apache সার্ভারের একটি উদাহরণ -',
 'You can manage all your storage files from' => 'আপনি এখান থেকে আপনার সমস্ত স্টোরেজ ফাইল পরিচালনা করতে পারেন',
 'You can manage your campaign discount from :campaign_discount_link.' => 'আপনি :campaign ডিসকাউন্ট লিঙ্ক থেকে আপনার প্রচারাভিযানের ডিসকাউন্ট পরিচালনা করতে পারেন।',
 'You can manage your coupon discount from :coupon_discount_link.' => 'আপনি :coupon ডিসকাউন্ট লিঙ্ক থেকে আপনার কুপন ডিসকাউন্ট পরিচালনা করতে পারেন।',
 'You can manage your normal discount from :normal_discount_link.' => 'আপনি :normal ডিসকাউন্ট লিঙ্ক থেকে আপনার স্বাভাবিক ডিসকাউন্ট পরিচালনা করতে পারেন।',
 'You can not consume your subscription after :date' => 'আপনি :date পরে আপনার সদস্যতা গ্রহণ করতে পারবেন না',
 'You can not turn off the SMS configuration status since the Phone verification status is active in login setup' => 'লগইন সেটআপে ফোন যাচাইকরণ স্থিতি সক্রিয় থাকায় আপনি SMS কনফিগারেশন স্থিতি বন্ধ করতে পারবেন না',
 'You can not turn off the email configuration status since the Email verification status is active in login setup' => 'লগইন সেটআপে ইমেল যাচাইকরণ স্থিতি সক্রিয় থাকায় আপনি ইমেল কনফিগারেশন স্থিতি বন্ধ করতে পারবেন না',
 'You can not undo this after deleting this logs' => 'এই লগগুলি মুছে ফেলার পরে আপনি এটি পূর্বাবস্থায় ফিরিয়ে আনতে পারবেন না৷',
 'You can now access your account & reset your password from our app & website.' => 'আপনি এখন আপনার অ্যাকাউন্ট অ্যাক্সেস করতে পারেন এবং আমাদের অ্যাপ এবং ওয়েবসাইট থেকে আপনার পাসওয়ার্ড রিসেট করতে পারেন।',
 'You can offer providers a free trial to experience the system overall.' => 'সামগ্রিকভাবে সিস্টেমের অভিজ্ঞতা নিতে আপনি প্রদানকারীদের একটি বিনামূল্যের ট্রায়াল দিতে পারেন।',
 'You can only add up to 10 custom pages.' => 'আপনি শুধুমাত্র 10টি পর্যন্ত কাস্টম পৃষ্ঠা যোগ করতে পারেন।',
 'You can see all inactive suspended providers on the :provider_list_link page.' => 'আপনি :provider তালিকা লিঙ্ক পৃষ্ঠায় সমস্ত নিষ্ক্রিয় স্থগিত প্রদানকারী দেখতে পারেন।',
 'You can see all providers service man list from this' => 'আপনি এখান থেকে সব প্রোভাইডার সার্ভিস ম্যান লিস্ট দেখতে পারবেন',
 'You can see status wise advertisement history and adjust edit, pause, resume, resubmit, or delete as needed.' => 'আপনি স্থিতি অনুসারে বিজ্ঞাপনের ইতিহাস দেখতে পারেন এবং প্রয়োজন অনুসারে সম্পাদনা, বিরতি, পুনরায় শুরু, পুনরায় জমা দিতে বা মুছতে সামঞ্জস্য করতে পারেন।',
 'You can see status wise advertisement history and adjust priority.' => 'আপনি স্ট্যাটাস অনুযায়ী বিজ্ঞাপনের ইতিহাস দেখতে এবং অগ্রাধিকার সামঞ্জস্য করতে পারেন।',
 'You can use any of our secure payment method & get selected subscription plan features' => 'আপনি আমাদের নিরাপদ পেমেন্ট পদ্ধতি ব্যবহার করতে পারেন এবং নির্বাচিত সদস্যতা পরিকল্পনা বৈশিষ্ট্য পেতে পারেন',
 'You can use the same API for both fields without any restrictions.' => 'আপনি কোন সীমাবদ্ধতা ছাড়াই উভয় ক্ষেত্রের জন্য একই API ব্যবহার করতে পারেন।',
 'You can withdraw this amount from Admin, as you have more receivable balance than cash in hand.' => 'আপনি অ্যাডমিনের কাছ থেকে এই পরিমাণ উত্তোলন করতে পারেন, কারণ আপনার হাতে নগদ অর্থের চেয়ে বেশি প্রাপ্য ব্যালেন্স রয়েছে।',
 'You can withdraw this amount from the Admin.' => 'আপনি অ্যাডমিনের কাছ থেকে এই পরিমাণ উত্তোলন করতে পারেন।',
 'You cannot activate both storage connection statuses at the same time. You must activate at least one status' => 'আপনি একই সময়ে উভয় স্টোরেজ সংযোগ স্থিতি সক্রিয় করতে পারবেন না। আপনাকে অন্তত একটি স্ট্যাটাস সক্রিয় করতে হবে',
 'You cannot change your own role status' => 'আপনি নিজের ভূমিকার অবস্থা পরিবর্তন করতে পারবেন না',
 'You cannot change your own status' => 'আপনি আপনার নিজের অবস্থা পরিবর্তন করতে পারবেন না',
 'You cannot delete your own profile' => 'আপনি আপনার নিজের প্রোফাইল মুছে ফেলতে পারবেন না',
 'You cannot delete your own role' => 'আপনি আপনার নিজের ভূমিকা মুছে ফেলতে পারবেন না',
 'You cannot edit your own role' => 'আপনি আপনার নিজের ভূমিকা সম্পাদনা করতে পারবেন না',
 'You cannot modify your own permissions.' => 'আপনি আপনার নিজের অনুমতি পরিবর্তন করতে পারবেন না.',
 'You cannot modify your own role' => 'আপনি আপনার নিজের ভূমিকা সংশোধন করতে পারবেন না',
 'You cannot set permissions on your own profile' => 'আপনি আপনার নিজের প্রোফাইলে অনুমতি সেট করতে পারবেন না',
 'You cannot undo this after deleting the selected logs.' => 'নির্বাচিত লগগুলি মুছে ফেলার পরে আপনি এটিকে পূর্বাবস্থায় ফেরাতে পারবেন না৷',
 'You can’t delete the ad' => 'আপনি বিজ্ঞাপন মুছে ফেলতে পারবেন না',
 'You did not create any advertisement yet!' => 'আপনি এখনো কোনো বিজ্ঞাপন তৈরি করেননি!',
 'You don’t have any reviews yet.' => 'আপনার এখনও কোনো পর্যালোচনা নেই।',
 'You have Earned a Referral Reward!' => 'আপনি একটি রেফারেল পুরস্কার জিতেছেন!',
 'You have Earned a Reward!' => 'আপনি একটি পুরস্কার জিতেছেন!',
 'You have cash in hand, you have to pay the due to delete your account.' => 'আপনার হাতে নগদ আছে, আপনার অ্যাকাউন্ট মুছে ফেলার জন্য আপনাকে বকেয়া পরিশোধ করতে হবে।',
 'You have earned a reward for referring a new user, who has now completed their first booking using your code...' => 'আপনি একজন নতুন ব্যবহারকারীকে উল্লেখ করার জন্য একটি পুরস্কার অর্জন করেছেন, যিনি এখন আপনার কোড ব্যবহার করে তাদের প্রথম বুকিং সম্পন্ন করেছেন...',
 'You have earned a reward for sign up with a referral code and first booking...' => 'আপনি একটি রেফারেল কোড এবং প্রথম বুকিং দিয়ে সাইন আপ করার জন্য একটি পুরস্কার জিতেছেন...',
 'You have the option to either switch all providers plans or allow providers to make changes.' => 'আপনার কাছে সমস্ত প্রদানকারীর প্ল্যান পরিবর্তন করার বা প্রদানকারীদের পরিবর্তন করার অনুমতি দেওয়ার বিকল্প আছে।',
 'You have to give a certain percentage of commission to admin for every booking request' => 'প্রতিটি বুকিং অনুরোধের জন্য আপনাকে প্রশাসককে একটি নির্দিষ্ট শতাংশ কমিশন দিতে হবে',
 'You have to pay a certain amount in every month / year to admin as subscription fee' => 'সাবস্ক্রিপশন ফি হিসাবে আপনাকে প্রতি মাসে/বছরে একটি নির্দিষ্ট পরিমাণ অ্যাডমিনকে দিতে হবে',
 'You have to pay this amount to Admin, as you have more cash in hand balance than receivable balance' => 'আপনাকে এই পরিমাণ প্রশাসককে দিতে হবে, কারণ আপনার হাতে প্রাপ্য ব্যালেন্সের চেয়ে বেশি নগদ আছে৷',
 'You have to pay this amount to the Admin. As after adjusting the both receivable and cash in hand balance, you have more cash in hand balance than receivable balance' => 'এই পরিমাণ আপনাকে অ্যাডমিনকে দিতে হবে। প্রাপ্তিযোগ্য এবং নগদ হাতে ব্যালেন্স উভয় সামঞ্জস্য করার পরে, আপনার হাতে প্রাপ্য ব্যালেন্সের চেয়ে বেশি নগদ আছে',
 'You have to setup a SMS module from below fist to active this feature' => 'এই বৈশিষ্ট্যটি সক্রিয় করতে আপনাকে নীচের মুষ্টি থেকে একটি এসএমএস মডিউল সেটআপ করতে হবে',
 'You have to verify the booking because of maximum amount exceed' => 'সর্বাধিক পরিমাণ অতিক্রম করার কারণে আপনাকে বুকিং যাচাই করতে হবে',
 'You have uploaded a wrong format file, please upload the right file.' => 'আপনি একটি ভুল ফর্ম্যাট ফাইল আপলোড করেছেন, দয়া করে সঠিক ফাইল আপলোড করুন৷',
 'You haven’t any conversation yet' => 'আপনি এখনও কোনো কথোপকথন নেই',
 'You must activate at least one digital payment method that supports your system currency (:currency).' => 'আপনাকে অবশ্যই অন্তত একটি ডিজিটাল পেমেন্ট পদ্ধতি সক্রিয় করতে হবে যা আপনার সিস্টেম কারেন্সি (:currency) সমর্থন করে।',
 'You must select at least one system when activating Maintenance Mode.' => 'রক্ষণাবেক্ষণ মোড সক্রিয় করার সময় আপনাকে অন্তত একটি সিস্টেম নির্বাচন করতে হবে।',
 'You must set up :firebase_configuration to make notifications work.' => 'বিজ্ঞপ্তিগুলি কাজ করার জন্য আপনাকে অবশ্যই :firebase কনফিগারেশন সেট আপ করতে হবে৷',
 'You must setup for V3 version. Otherwise the default reCAPTCHA will be displayed automatically' => 'আপনাকে অবশ্যই V3 সংস্করণের জন্য সেটআপ করতে হবে। অন্যথায় ডিফল্ট reCAPTCHA স্বয়ংক্রিয়ভাবে প্রদর্শিত হবে',
 'You must update your location first' => 'আপনাকে প্রথমে আপনার অবস্থান আপডেট করতে হবে',
 'You need to go to the Customer Location to provide the service' => 'পরিষেবা প্রদানের জন্য আপনাকে গ্রাহকের অবস্থানে যেতে হবে',
 'You now have access to all the premium features included in your selected plan.' => 'এখন আপনার নির্বাচিত প্ল্যানে অন্তর্ভুক্ত সমস্ত প্রিমিয়াম বৈশিষ্ট্যগুলিতে অ্যাক্সেস রয়েছে৷',
 'You offer will be removed for the post' => 'পোস্টের জন্য আপনার অফারটি সরানো হবে',
 'You want to Turn Off the Push Notification Status' => 'আপনি পুশ বিজ্ঞপ্তি স্থিতি বন্ধ করতে চান',
 'You want to Turn On the Push Notification Status' => 'আপনি পুশ বিজ্ঞপ্তি স্থিতি চালু করতে চান',
 'You want to turn Off the social media status' => 'আপনি সামাজিক মিডিয়া স্ট্যাটাস বন্ধ করতে চান',
 'You want to turn On this social media status' => 'আপনি এই সামাজিক মিডিয়া স্ট্যাটাস চালু করতে চান',
 'You will get access to all the features and options in the provider panel, app, and interaction with users.' => 'আপনি প্রদানকারী প্যানেল, অ্যাপ এবং ব্যবহারকারীদের সাথে মিথস্ক্রিয়াতে সমস্ত বৈশিষ্ট্য এবং বিকল্পগুলিতে অ্যাক্সেস পাবেন।',
 'You will get access to all the features and options in the store panel, app, and interaction with users.' => 'আপনি স্টোর প্যানেল, অ্যাপ এবং ব্যবহারকারীদের সাথে মিথস্ক্রিয়াতে সমস্ত বৈশিষ্ট্য এবং বিকল্পগুলিতে অ্যাক্সেস পাবেন।',
